{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 Bucket Public Access Block Missing",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The S3 bucket lacks an explicit public access block configuration, which is a critical security control to prevent accidental data exposure."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 Bucket Encryption Not Configured",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The bucket does not have server-side encryption configured (e.g., SSE-S3 or SSE-KMS), leaving CloudTrail logs unencrypted at rest."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 Bucket Versioning Disabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled on the bucket, meaning accidental deletions or overwrites of audit logs cannot be recovered."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 Bucket Access Logging Disabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "Server access logging is not enabled, preventing visibility into who accessed the CloudTrail log files."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket = "fleet-management-gps-tracking-system-cloudtrail-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "cloudtrail_logs" {
  bucket        = aws_s3_bucket.cloudtrail_logs.id
  target_bucket = aws_s3_bucket.cloudtrail_logs.id # In production, use a separate secure logging bucket
  target_prefix = "log/"
}",
  "fix_summary": "Added `aws_s3_bucket_public_access_block` to enforce strict public access restrictions. Added `aws_s3_bucket_server_side_encryption_configuration` with AES256 for encryption at rest. Enabled versioning via `aws_s3_bucket_versioning` and configured access logging via `aws_s3_bucket_logging` to meet security best practices for audit logs."
}
